<template>
  <div class="app-container pipeline-page pipeline-model-page">
    <div class="pipeline-page-head"><div><span class="pipeline-eyebrow">MODEL & PROMPT</span><h1>模型与 Prompt</h1><p class="summary">集中配置模型网关、业务场景参数和 Prompt 版本，所有变更均进入审计记录。</p></div><div class="pipeline-head-actions"><el-button :icon="DocumentChecked" @click="auditVisible = true">变更记录</el-button><el-button type="primary" :icon="Plus" @click="openModelDialog">添加模型</el-button></div></div>
    <div class="model-overview"><article><span>可用模型</span><strong>4 / 5</strong><small class="is-success">服务正常</small></article><article><span>今日调用</span><strong>2,846</strong><small>成功率 99.2%</small></article><article><span>平均响应</span><strong>3.8s</strong><small>较昨日 -0.4s</small></article><article><span>Prompt 版本</span><strong>18</strong><small>3 个待发布</small></article></div>
    <el-tabs v-model="activeTab" class="model-tabs">
      <el-tab-pane label="模型配置" name="models"><div class="model-grid"><article v-for="model in models" :key="model.id"><header><span class="model-logo" :style="{ background: model.color }">{{ model.short }}</span><div><strong>{{ model.name }}</strong><small>{{ model.provider }} · {{ model.protocol }}</small></div><el-switch v-model="model.enabled" /></header><dl><div><dt>适用场景</dt><dd>{{ model.scenes.join('、') }}</dd></div><div><dt>上下文长度</dt><dd>{{ model.context }}</dd></div><div><dt>温度参数</dt><dd>{{ model.temperature }}</dd></div><div><dt>最近检测</dt><dd>{{ model.checkedAt }}</dd></div></dl><footer><span :class="{ 'is-error': model.health !== '正常' }"><i></i>{{ model.health }}</span><div><el-button link @click="testModel(model)">连通测试</el-button><el-button link type="primary" @click="editModel(model)">配置</el-button></div></footer></article></div></el-tab-pane>
      <el-tab-pane label="Prompt 管理" name="prompts"><div class="prompt-layout"><aside><button v-for="scene in scenes" :key="scene.value" type="button" :class="{ 'is-active': activeScene === scene.value }" @click="activeScene = scene.value"><component :is="scene.icon" /><span><strong>{{ scene.name }}</strong><small>{{ scene.description }}</small></span><b>{{ promptCount(scene.value) }}</b></button></aside><main><el-alert class="prompt-connect-note" title="数据过滤与清洗已接入真实版本管理。发布后，后续采集运行会固定保存所使用的 Prompt 快照。" type="info" :closable="false" /><div class="prompt-toolbar"><el-input v-model="promptKeyword" :prefix-icon="Search" clearable placeholder="搜索 Prompt 名称或用途" /><el-button type="primary" :icon="Plus" @click="openPromptDialog">新建 Prompt</el-button></div><el-table v-loading="promptLoading" :data="filteredPrompts"><el-table-column prop="name" label="Prompt 名称" min-width="240"><template #default="{ row }"><div class="prompt-name"><strong>{{ row.name }}</strong><small>{{ row.description }}</small></div></template></el-table-column><el-table-column prop="version" label="当前版本" width="100" /><el-table-column prop="scene" label="场景" width="130"><template #default="{ row }">{{ sceneLabel(row.scene) }}</template></el-table-column><el-table-column label="状态" width="150"><template #default="{ row }"><el-tag :type="row.status === 'published' ? 'success' : 'warning'" effect="plain">{{ row.status === 'published' ? '已发布' : row.status === 'retired' ? '已归档' : '草稿' }}</el-tag><small class="test-state" :class="`is-${row.testStatus}`">{{ testStatusLabel(row.testStatus) }}</small></template></el-table-column><el-table-column prop="updatedAt" label="更新时间" width="180" /><el-table-column label="操作" width="270"><template #default="{ row }"><el-button link type="primary" @click="editPrompt(row)">编辑</el-button><el-button link @click="runPromptTest(row)">离线测试</el-button><el-button link type="success" :disabled="row.status === 'published' || row.testStatus !== 'passed'" @click="publishPrompt(row)">发布</el-button></template></el-table-column></el-table></main></div></el-tab-pane>
      <el-tab-pane label="场景路由" name="routing"><el-card shadow="never"><el-table :data="sceneRoutes"><el-table-column prop="scene" label="业务场景" min-width="220" /><el-table-column prop="primary" label="主模型" min-width="180" /><el-table-column prop="fallback" label="备用模型" min-width="180" /><el-table-column prop="timeout" label="超时" width="100" /><el-table-column prop="dailyLimit" label="日限额" width="120" /><el-table-column label="操作" width="100"><template #default><el-button link type="primary">编辑路由</el-button></template></el-table-column></el-table></el-card></el-tab-pane>
    </el-tabs>
    <el-dialog v-model="modelDialogVisible" :title="editingModel ? '配置模型' : '添加模型'" width="620px"><el-form label-position="top"><div class="model-form-grid"><el-form-item label="模型名称"><el-input v-model="modelForm.name" /></el-form-item><el-form-item label="服务商"><el-input v-model="modelForm.provider" /></el-form-item><el-form-item label="接口地址" class="is-full"><el-input v-model="modelForm.endpoint" /></el-form-item><el-form-item label="模型标识"><el-input v-model="modelForm.modelId" /></el-form-item><el-form-item label="协议类型"><el-select v-model="modelForm.protocol"><el-option label="OpenAI Compatible" value="openai" /><el-option label="Custom Gateway" value="custom" /></el-select></el-form-item><el-form-item label="API 密钥" class="is-full"><el-input v-model="modelForm.apiKey" type="password" show-password placeholder="密钥仅加密保存，不会在页面回显" /></el-form-item></div></el-form><template #footer><el-button @click="modelDialogVisible = false">取消</el-button><el-button @click="ElMessage.success('连通测试通过')">测试连接</el-button><el-button type="primary" @click="saveModel">保存配置</el-button></template></el-dialog>
    <el-drawer v-model="promptDialogVisible" :title="editingPrompt ? `编辑 ${promptForm.name}` : '新建 Prompt'" size="720px"><el-form label-position="top"><el-form-item label="Prompt 编码"><el-input v-model="promptForm.promptKey" :disabled="Boolean(editingPrompt)" placeholder="例如：data-filter" /></el-form-item><el-form-item label="业务场景"><el-select v-model="promptForm.scene" :disabled="Boolean(editingPrompt)"><el-option v-for="scene in scenes.filter(item => item.value !== 'all')" :key="scene.value" :label="scene.name" :value="scene.value" /></el-select></el-form-item><el-form-item label="Prompt 名称"><el-input v-model="promptForm.name" /></el-form-item><el-form-item label="用途说明"><el-input v-model="promptForm.description" /></el-form-item><el-form-item label="系统提示词"><el-input v-model="promptForm.system" type="textarea" :rows="8" /></el-form-item><el-form-item label="用户提示词模板"><el-input v-model="promptForm.user" type="textarea" :rows="8" /></el-form-item><el-alert title="数据过滤支持变量：{{title}}、{{body}}、{{summary}}、{{source}}、{{publishedAt}}。必须明确输出 keep、score、reason；当前测试为离线结构测试，不会把私有资料发送到外部模型。" type="info" :closable="false" /></el-form><template #footer><el-button @click="promptDialogVisible = false">取消</el-button><el-button :loading="promptSaving" @click="saveAndTestPrompt">保存并测试</el-button><el-button type="primary" :loading="promptSaving" @click="savePrompt">保存新版本</el-button></template></el-drawer>
    <el-drawer v-model="auditVisible" title="模型与 Prompt 变更记录" size="560px"><el-timeline><el-timeline-item v-for="item in auditLogs" :key="item.time" :timestamp="item.time" placement="top"><el-card shadow="never"><strong>{{ item.action }}</strong><p>{{ item.detail }}</p><small>{{ item.user }}</small></el-card></el-timeline-item></el-timeline></el-drawer>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { Document, DocumentChecked, MagicStick, Plus, Search, Tickets } from '@element-plus/icons-vue'
import { listPipelinePrompts, publishPipelinePrompt, savePipelinePrompt, testPipelinePrompt } from '@/api/pipeline/intelligence'

const activeTab = ref('models')
const activeScene = ref('all')
const promptKeyword = ref('')
const modelDialogVisible = ref(false)
const promptDialogVisible = ref(false)
const auditVisible = ref(false)
const editingModel = ref(null)
const editingPrompt = ref(null)
const models = ref([{ id: 1, short: 'R1', name: '科研写作主模型', provider: '企业模型网关', protocol: 'OpenAI Compatible', scenes: ['科研生成', '摘要'], context: '128K', temperature: 0.3, checkedAt: '5分钟前', health: '正常', enabled: true, color: '#2764e7' }, { id: 2, short: 'R2', name: '长文本分析模型', provider: '企业模型网关', protocol: 'OpenAI Compatible', scenes: ['文档解析', '质量检查'], context: '256K', temperature: 0.2, checkedAt: '8分钟前', health: '正常', enabled: true, color: '#0b8f87' }, { id: 3, short: 'T1', name: '中英翻译模型', provider: '内部推理服务', protocol: 'Custom Gateway', scenes: ['论文翻译'], context: '64K', temperature: 0.1, checkedAt: '12分钟前', health: '正常', enabled: true, color: '#7357c8' }, { id: 4, short: 'V1', name: '图形生成模型', provider: '内部推理服务', protocol: 'Custom Gateway', scenes: ['技术路线图'], context: '32K', temperature: 0.4, checkedAt: '26分钟前', health: '响应偏慢', enabled: true, color: '#c26a2e' }])
const promptLoading = ref(false)
const promptSaving = ref(false)
const scenes = [{ name: '全部 Prompt', value: 'all', description: '查看所有业务提示词', icon: Document }, { name: '科研报告', value: 'research', description: '大纲与章节生成', icon: MagicStick }, { name: '日报周月报', value: 'digest', description: '摘要与周期趋势研判', icon: Tickets }, { name: '数据过滤与清洗', value: 'data-filter', description: '采集内容相关性与风险筛选', icon: Tickets }]
const prompts = ref([])
const sceneRoutes = [{ scene: '科研报告生成', primary: '科研写作主模型', fallback: '长文本分析模型', timeout: '120s', dailyLimit: '2,000次' }, { scene: '文档解析与摘要', primary: '长文本分析模型', fallback: '科研写作主模型', timeout: '90s', dailyLimit: '5,000次' }, { scene: '技术路线图', primary: '图形生成模型', fallback: '科研写作主模型', timeout: '90s', dailyLimit: '1,000次' }]
const modelForm = reactive({ name: '', provider: '', endpoint: '', modelId: '', protocol: 'openai', apiKey: '' })
const promptForm = reactive({ promptKey: '', scene: 'data-filter', name: '', description: '', system: '你是管网科技情报过滤器。只能依据输入内容判断，不得补造事实。请输出 JSON：keep、score、reason、category、keywords。', user: '标题：{{title}}\n摘要：{{summary}}\n正文：{{body}}\n来源：{{source}}\n发布时间：{{publishedAt}}\n请判断是否保留，输出 keep（布尔）、score（0-100）、reason、category、keywords。' })
const auditLogs = [{ time: '2026-08-04 10:16', action: '发布 Prompt V3.1', detail: '科研章节生成 Prompt 通过 120 条离线测试集。', user: '管理员' }, { time: '2026-08-02 09:30', action: '修改模型参数', detail: '科研写作主模型 temperature 从 0.4 调整为 0.3。', user: '算法工程师' }]
const filteredPrompts = computed(() => prompts.value.filter(item => (activeScene.value === 'all' || item.scene === activeScene.value) && (!promptKeyword.value || `${item.name}${item.description}`.includes(promptKeyword.value))))
function promptCount(scene) { return scene === 'all' ? prompts.value.length : prompts.value.filter(item => item.scene === scene).length }
function sceneLabel(scene) { return ({ research: '科研报告', digest: '日报周月报', 'data-filter': '数据过滤与清洗' })[scene] || scene }
function testStatusLabel(status) { return ({ passed: '结构测试通过', failed: '测试未通过', untested: '未测试' })[status] || '未测试' }
function openModelDialog() { editingModel.value = null; Object.assign(modelForm, { name: '', provider: '', endpoint: '', modelId: '', protocol: 'openai', apiKey: '' }); modelDialogVisible.value = true }
function editModel(model) { editingModel.value = model; Object.assign(modelForm, { name: model.name, provider: model.provider, endpoint: 'https://model-gateway.example/v1', modelId: model.name, protocol: 'openai', apiKey: '' }); modelDialogVisible.value = true }
function saveModel() { modelDialogVisible.value = false; ElMessage.success('模型配置已保存并记录审计日志') }
function testModel(model) { ElMessage.success(`${model.name} 连通测试通过，响应 3.2 秒`) }
async function loadPrompts() { promptLoading.value = true; try { const res = await listPipelinePrompts(); prompts.value = res.data?.rows || [] } catch (error) { ElMessage.warning('提示词配置暂时无法加载') } finally { promptLoading.value = false } }
function openPromptDialog() { editingPrompt.value = null; Object.assign(promptForm, { promptKey: 'data-filter', scene: 'data-filter', name: '数据过滤与清洗', description: '对采集内容进行管网相关性、风险和发布资格筛选。' }); promptDialogVisible.value = true }
function editPrompt(prompt) { editingPrompt.value = prompt; Object.assign(promptForm, { promptKey: prompt.promptKey, scene: prompt.scene, name: prompt.name, description: prompt.description, system: prompt.systemPrompt, user: prompt.userPrompt }); promptDialogVisible.value = true }
async function savePrompt() { promptSaving.value = true; try { await savePipelinePrompt({ promptKey: promptForm.promptKey, scene: promptForm.scene, name: promptForm.name, description: promptForm.description, systemPrompt: promptForm.system, userPrompt: promptForm.user }); promptDialogVisible.value = false; ElMessage.success('Prompt 新版本已保存为草稿'); await loadPrompts() } catch (error) { ElMessage.error(error?.msg || 'Prompt 保存失败') } finally { promptSaving.value = false } }
async function saveAndTestPrompt() { promptSaving.value = true; try { await savePipelinePrompt({ promptKey: promptForm.promptKey, scene: promptForm.scene, name: promptForm.name, description: promptForm.description, systemPrompt: promptForm.system, userPrompt: promptForm.user }); const res = await testPipelinePrompt(promptForm.promptKey); ElMessage.success(res.msg || '离线结构测试通过'); promptDialogVisible.value = false; await loadPrompts() } catch (error) { ElMessage.error(error?.msg || 'Prompt 测试未通过') } finally { promptSaving.value = false } }
async function runPromptTest(prompt) { try { const res = await testPipelinePrompt(prompt.promptKey); ElMessage.success(res.msg || '离线结构测试通过'); await loadPrompts() } catch (error) { ElMessage.error(error?.msg || 'Prompt 测试未通过') } }
async function publishPrompt(prompt) { try { await publishPipelinePrompt(prompt.promptKey); ElMessage.success('Prompt 已发布，后续采集将使用该版本'); await loadPrompts() } catch (error) { ElMessage.error(error?.msg || 'Prompt 发布失败') } }
onMounted(loadPrompts)
</script>

<style scoped>
.model-overview { margin-bottom: 18px; display: grid; grid-template-columns: repeat(4,1fr); gap: 14px; }.model-overview article { padding: 20px; border: 1px solid #e2e8f0; border-radius: 10px; display: flex; flex-direction: column; background: #fff; }.model-overview span,.model-overview small { color: #64748b; font-size: 11px; }.model-overview strong { margin: 8px 0 4px; color: #0f172a; font-size: 27px; }.model-overview small.is-success { color: #14845d; }
.prompt-connect-note { margin-bottom: 12px; }.test-state { display: block; margin-top: 4px; color: #64748b; font-size: 11px; }.test-state.is-passed { color: #14845d; }.test-state.is-failed { color: #c2410c; }
.model-tabs { padding: 0 20px 20px; border: 1px solid #e2e8f0; border-radius: 10px; background: #fff; }.model-grid { display: grid; grid-template-columns: repeat(2,1fr); gap: 14px; }.model-grid article { padding: 20px; border: 1px solid #e2e8f0; border-radius: 9px; }.model-grid header { display: grid; grid-template-columns: 42px 1fr auto; gap: 11px; align-items: center; }.model-logo { width: 42px; height: 42px; border-radius: 10px; display: grid; place-items: center; color: #fff; font-size: 12px; font-weight: 800; }.model-grid header > div { display: flex; flex-direction: column; }.model-grid header small { margin-top: 3px; color: #64748b; font-size: 10px; }.model-grid dl { margin: 16px 0; }.model-grid dl div { padding: 6px 0; border-bottom: 1px solid #edf1f6; display: flex; justify-content: space-between; font-size: 10px; }.model-grid dt { color: #64748b; }.model-grid dd { margin: 0; color: #334155; }.model-grid footer { display: flex; align-items: center; justify-content: space-between; }.model-grid footer > span { display: flex; align-items: center; gap: 6px; color: #14845d; font-size: 10px; }.model-grid footer > span.is-error { color: #c26a2e; }.model-grid footer i { width: 7px; height: 7px; border-radius: 50%; background: currentColor; }.prompt-layout { display: grid; grid-template-columns: 220px minmax(0,1fr); gap: 16px; }.prompt-layout > aside { padding: 8px; border: 1px solid #e2e8f0; border-radius: 9px; align-self: start; }.prompt-layout > aside button { width: 100%; min-height: 58px; padding: 8px; border: 0; border-radius: 7px; display: grid; grid-template-columns: 20px 1fr auto; gap: 8px; align-items: center; background: transparent; color: #475569; cursor: pointer; text-align: left; }.prompt-layout > aside button.is-active { background: #edf3ff; color: #2764e7; }.prompt-layout > aside svg { width: 16px; }.prompt-layout > aside span { display: flex; flex-direction: column; }.prompt-layout > aside strong { font-size: 11px; }.prompt-layout > aside small { margin-top: 3px; color: #64748b; font-size: 9px; }.prompt-layout > aside b { font-size: 10px; }.prompt-toolbar { margin-bottom: 12px; display: grid; grid-template-columns: 1fr auto; gap: 10px; }.prompt-name { display: flex; flex-direction: column; }.prompt-name small { margin-top: 4px; color: #64748b; font-size: 10px; }.model-form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 0 14px; }.model-form-grid .is-full { grid-column: 1/-1; }
@media(max-width:960px){.model-overview{grid-template-columns:repeat(2,1fr)}.model-grid{grid-template-columns:1fr}.prompt-layout{grid-template-columns:1fr}}@media(max-width:600px){.model-overview,.model-form-grid{grid-template-columns:1fr}.prompt-toolbar{grid-template-columns:1fr}}
</style>
